import{_ as l,l as i,o as e,c as n,v as t,p as s,x as o,d as p,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"RAG 中的上下文压缩","description":"","frontmatter":{"title":"RAG 中的上下文压缩","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-context-compression.md","filePath":"llm/rag-context-compression.md","lastUpdated":1789023840000}'),m={name:"llm/rag-context-compression.md"};function c(h,a,A,_,u,f){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="rag-中的上下文压缩" tabindex="-1">RAG 中的上下文压缩 <a class="header-anchor" href="#rag-中的上下文压缩" aria-label="Permalink to &quot;RAG 中的上下文压缩&quot;">​</a></h1><div class="epigraph"><p>Top-k 块里只有几句在支撑答案，其余占窗口、占注意力、诱使胡编。压缩的是证据，不是把提示缩成口号。</p><footer>—— 对照 LLMLingua 一类提示压缩；RECOMP 一类针对检索块的压缩</footer></div><p><a href="/llm/adaptive-rag">上一课</a>决定检索之后，窗口仍可能被 \\(k\\) 块填满。主干已有<a href="/llm/prompt-compression">提示压缩</a>与检索式压缩；本课钉 RAG 场景：在<strong>保支撑</strong>的前提下缩短。缺口不是再讲 tokenizer，而是压缩与归因的冲突——删掉的句子可能正是引用对象。后课 ANN 结构默认：召回的候选可以多，送进阅读器的 token 必须少。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>压缩器若只优化语言建模困惑度，会留下流畅套话、删掉数字与约束。RAG 需要的是查询条件下的抽取或摘要：留下能支撑答案的句。Xu 等 RECOMP 训练压缩器服务下游 QA。LLMLingua 更偏通用提示压缩，用于 RAG 时必须用任务分数验收，不能只看压缩率。</p><p>压缩后再引用：ID 必须仍指向未压缩块或可逆片段，否则归因课的可解析率崩掉。</p><p><span class="marginnote">把压缩交给阅读器自己「先看目录」而不删 token，是注意力税，不是压缩。真压缩要减少进入 softmax 的 token。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两种：抽取式（选句，可逆、好引用）与生成式摘要（更短、可能不忠）。先抽取后摘要。保留查询词命中句与高 BM25 句作下限。评测：压缩率、忠实度、答案正确、引用可解析。与切分重叠一起调：先切好再压，比先压整页再切更可控。</p>',9)),(e(),s(E,null,{default:o(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%22%E6%A3%80%E7%B4%A2%E5%9D%97%22%5D%20--%3E%20EXT%5B%22%E6%8A%BD%E5%8F%96%E5%85%B3%E9%94%AE%E5%8F%A5%22%5D%0A%20%20EXT%20--%3E%20SUM%5B%22%E5%8F%AF%E9%80%89%E6%91%98%E8%A6%81%22%5D%0A%20%20SUM%20--%3E%20READ%5B%22%E9%98%85%E8%AF%BB%E5%99%A8%22%5D%0A%20%20EXT%20--%3E%20CIT%5B%22%E5%BC%95%E7%94%A8%E4%BB%8D%E6%8C%87%E5%90%91%E5%8E%9F%E5%9D%97%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>窗口里的无关句成为干扰负例，注意力与参数记忆都会被带偏，忠实度下降。压缩是在测试时做一次信息瓶颈，逼迫阅读器只看见高相关子集。瓶颈若由未校准的 LLM 摘要实现，会引入新幻觉层——必须用支撑指标挡。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>法律原文不可生成式压缩。下一课把「候选可以很多」交给 HNSW / IVF：那是索引层的近似，不是窗口层的压缩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RAG 压缩保支撑与可引用，不以 PPL 或压缩率为第一指标。</li><li>抽取优于盲目摘要；引用指向原块。</li><li>用 QA 与忠实度验收，不用压缩率发版。</li><li>出处：RECOMP；LLMLingua；提示压缩课。</li></ul>',6))])}const g=l(m,[["render",c]]);export{B as __pageData,g as default};
